def hex_word_sum(input_string):
    def is_valid_hex_word(word):
        try:
            return all(c in '0123456789' or c.upper() in 'ABCDEF' for c in word.upper().replace('O', '0').replace('S', '5'))
        except ValueError:
            return False

    def hex_word_to_decimal(word):
        return int(word.upper().replace('O', '0').replace('S', '5'), 16)

    words = input_string.split()
    valid_hex_words = [word for word in words if is_valid_hex_word(word)]
    return sum(hex_word_to_decimal(word) for word in valid_hex_words)

# Example usage:
print(hex_word_sum('BAG OF BEES'))  # Output: 48884
